mapper.select:
select t1.agent_id as id, t1.name, t1.description, t1.icon, t1.creator, t4.version_id, t4.version_name from ( select agent_id, name, description, icon, creator from t_agent where project_id = #{projectId,jdbcType=VARCHAR} and deleted = false
and agent_id = #{searchCriteria.id,jdbcType=VARCHAR}
and workspace_id = #{searchCriteria.workspaceId,jdbcType=VARCHAR}
and name like concat('%', #{searchCriteria.name,jdbcType=VARCHAR}, '%') escape '!'
and type = #{searchCriteria.type,jdbcType=VARCHAR}
and sub_type = #{searchCriteria.subType,jdbcType=VARCHAR}
) t1 inner join ( select t2.app_id as id, t2.version_id as version_id, t2.version_name as version_name from t_release_version t2 inner join ( select app_id, MAX(version_id) as max_version_id from t_release_version group by app_id ) t3 on t2.app_id = t3.app_id and t2.version_id = t3.max_version_id ) t4 on t1.agent_id = t4.id

